head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[datePicker > M > getValue]<br/>DatePicker 컴포넌트에서 현재 선택된 날짜값을 문자열로 반환합니다. 반환되는 문자열의 포맷은 calendarValueType 속성값에 따라 결정됩니다.",
    "validation" : [
        "DatePicker 컴포넌트에서 현재 선택된 날짜값을 문자열로 반환합니다. 반환되는 문자열의 포맷은 calendarValueType 속성값에 따라 결정됩니다.",
        "String 타입으로 현재 선택된 날짜값을 반환합니다.",
        "calendarValueType='yearMonth' 인 경우 'yyyyMM' 포맷의 6자리 문자열을 반환합니다.",
        "calendarValueType='yearMonthDate' 인 경우 'yyyyMMdd' 포맷의 8자리 문자열을 반환합니다.",
        "calendarValueType='yearMonthDateTime' 인 경우 'yyyyMMddHHmm' 포맷의 12자리 문자열을 반환합니다.",
        "calendarValueType='hourMinute' 인 경우 'HHmm' 포맷의 4자리 문자열을 반환합니다.",
        "시간값은 24시간제로 반환됩니다."
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let calendarValueType = con_calendarValueType.getText();

    let properties = {
        calendarValueType : calendarValueType
    }

    let cList = $c.gcm.createCList(properties);

    await $c.gcm.createBasicDatePicker(cList);

    // calendarValueType 별 setValue 포맷 보정
    // (createBasicDatePicker 기본 '20250101' 8자리 / 24시간제 확인을 위해 14시 입력)
    // yearMonth=6 / yearMonthDate=8 / yearMonthDateTime=12 / hourMinute=4
    if (calendarValueType === "yearMonth") {
        target1.setValue("202501");
    } else if (calendarValueType === "yearMonthDateTime") {
        target1.setValue("202501011430");
    } else if (calendarValueType === "hourMinute") {
        target1.setValue("1430");
    }
}



// getValue() 반환값 / 타입 / 자릿수 출력
scwin.btn_getValue_onclick = function (e) {
    let rtn = target1.getValue();
    let valueType = target1.options.calendarValueType || 'yearMonthDate';

    wf_body_bottom.getObj("scwin").setReturnValue("[getValue() 반환값] '" + rtn + "'");
    wf_body_bottom.getObj("scwin").setReturnValue("[반환 타입] " + typeof rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("[반환 문자열 자릿수] " + rtn.length + "자리");

    // 24시간제 검증: yearMonthDateTime / hourMinute 인 경우 입력한 14시가 '14' 로 포함되는지 확인
    if (valueType === 'yearMonthDateTime' || valueType === 'hourMinute') {
        let hourPart = (valueType === 'yearMonthDateTime') ? rtn.substring(8, 10) : rtn.substring(0, 2);
        wf_body_bottom.getObj("scwin").setReturnValue("[24시간제 시(HH) 부분] '" + hourPart + "' (14 포함 여부: " + (hourPart === '14') + ")");
    }
};
